hooks.command:
python3 -c "import json,subprocess,sys;exec('payload=sys.stdin.read();parsed=False
try:
 e=json.loads(payload)
 if not isinstance(e,dict) or not isinstance(e.get('tool_name'),str) or not e['tool_name']: raise ValueError('Invalid event')
 n=e['tool_name'];a=e.get('tool_input',{})
 if a is None: a={}
 if not isinstance(a,dict): raise ValueError('Invalid tool input')
 q=str(a.get('command',a.get('cmd','')))
 guarded=(n in {'Agent','Task'} and a.get('subagent_type') not in {'Plan','Explore'}) or n.endswith('forgejo_pr_merge') or n.endswith('production_admission') or 'factory/bin/seat.sh' in q
 parsed=True
except Exception:
 guarded=True
try:
 if not parsed: raise ValueError('Invalid event')
 r=subprocess.run([sys.executable,sys.argv[1],'pre'],input=payload,text=True,capture_output=True,timeout=8)
 if r.returncode: raise RuntimeError('Hook child failed')
 if r.stdout:
  output=json.loads(r.stdout)
  if not isinstance(output,dict) or set(output)!={'hookSpecificOutput'}: raise ValueError('Invalid hook output')
  h=output.get('hookSpecificOutput')
  if not isinstance(h,dict) or set(h)-{'hookEventName','permissionDecision','permissionDecisionReason'} or h.get('hookEventName')!='PreToolUse' or h.get('permissionDecision') not in {'allow','deny','ask'} or not isinstance(h.get('permissionDecisionReason',''),str): raise ValueError('Invalid decision')
 sys.stdout.write(r.stdout)
except Exception:
 if guarded: print(json.dumps({'hookSpecificOutput':{'hookEventName':'PreToolUse','permissionDecision':'deny','permissionDecisionReason':'Improve checkpoint hook failed or timed out; repair the plugin before this transition. Reads and planning remain available.'}}))
')" "${CLAUDE_PLUGIN_ROOT}/scripts/skill_gate.py" pre
